import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-04-20 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-04-20 :: Ceph Orchestration Meeting","date":"2020-04-20T00:00:00.000Z","updated":"2020-04-29T00:00:00.000Z","tags":["Ceph","Distributed Storage","CRUSH Algorithm","Scalability","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-20_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-04-20_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-04-20_-_-_Ceph_Orchestration_Meeting.md"};function o(h,e,n,s,u,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-每周会议" tabindex="-1">会议主题：Ceph 每周会议 <a class="header-anchor" href="#会议主题-ceph-每周会议" aria-label="Permalink to &quot;会议主题：Ceph 每周会议&quot;">​</a></h4><h4 id="日期-2020年4月20日" tabindex="-1">日期：2020年4月20日 <a class="header-anchor" href="#日期-2020年4月20日" aria-label="Permalink to &quot;日期：2020年4月20日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph 15.2.2 版本更新</strong></p><ul><li>更新包括大量针对用户当前遇到问题的 bug 修复。</li><li>改进了文档，帮助用户解决未预料到的问题和可用性问题。</li></ul></li><li><p><strong>主机移除问题</strong></p><ul><li>讨论了从 Ceph 集群中移除主机的用户体验问题，指出当前流程繁琐且容易出错。</li><li>发现调度器行为存在意外情况，例如在指定主机和数量时，调度器行为不符合预期。</li></ul></li><li><p><strong>调度器行为调整</strong></p><ul><li>讨论了调度器在处理特定放置规范时的行为，特别是当指定主机和数量不匹配时的处理方式。</li><li>决定调整调度器的行为，优先考虑主机的指定，并在无法满足放置规范时给出警告或拒绝配置。</li></ul></li><li><p><strong>Prometheus 监控堆栈的高可用性</strong></p><ul><li>讨论了如何提高 Prometheus 监控堆栈的高可用性，包括在多个节点上部署 Prometheus 服务器和使用代理进行负载均衡。</li><li>提出了在每个节点上复制监控堆栈的方案，以避免数据丢失和提高响应性。</li></ul></li><li><p><strong>Ceph 命令工具箱</strong></p><ul><li>介绍了新的 Ceph 命令工具箱，可以简化运行 Ceph 命令的操作，特别是在需要一次性操作或自动化脚本时。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>调整调度器的行为，优先考虑主机的指定，并在无法满足放置规范时给出警告或拒绝配置。</li><li>研究并实施 Prometheus 监控堆栈的高可用性方案。</li><li>继续完善 Ceph 命令工具箱，以简化管理和操作流程。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成调度器行为的调整，并确保现有集群的平稳迁移。</li><li>进一步讨论和细化 Prometheus 监控堆栈的高可用性方案。</li><li>继续开发和测试 Ceph 命令工具箱，确保其稳定性和实用性。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了 Kubernetes 和 Ceph 在处理节点不足时的行为差异。</li><li>讨论了如何简化监控堆栈的配置和管理，特别是在使用代理进行负载均衡时。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议于[具体时间]结束，下次会议定于下周同一时间进行。</li></ul><p>本次 Ceph 每周会议的纪要涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划，确保了 Ceph 分布式存储系统的持续优化和改进。</p>',15)])])}const c=a(r,[["render",o]]);export{_ as __pageData,c as default};
